// Deliberately NOT a lifetime or circulating supply cap; repeated minting passes.
contract FeeWallet<owner: PublicKey> {
    function spend(sig: Signature) { require(checksig(sig, owner)); }
}
token PerMintLimit<issuer: PublicKey, limit: Amount> {
    function issue(delta: Amount, sig: Signature) {
        require(delta <= limit);
        require(checksig(sig, issuer));
    }
}

// LC-1 PROPOSAL; current compiler must reject. See script-abi.md.
contract Owner<key: PublicKey> {
    entry spend(sig: Signature) { require(checksig(sig, key)); }
}
policy Holder<owner: ContractRootHash, rules: ContractRootHash> {
    branch authorization at 0 = owner;
    branch transfer_rules at 1 = rules;
    path transfer = all(authorization, transfer_rules);
    require every_path(transfer_rules);
}

// LC-1 PROPOSAL; current compiler must reject.
contract Allowance {
    state separate { remaining: Amount, nonce: Amount }
    entry consume(amount: Amount) transition {
        require(amount <= remaining);
        remaining = remaining - amount;
        nonce = nonce + 1;
    }
}

// P03 has DIV; the current frontend has no division syntax.
contract Quotient {
    function check(a: Int, b: Int, q: Int) { require(a / b == q); }
}

// P03 has CHECKDATASIG; this proposed binding is not in the current frontend.
contract Permit<owner: PublicKey> {
    function consume(sig: Signature, digest: Bytes32) {
        require(checkdatasig(sig, digest, owner, 0));
    }
}
